def validate_instance(template, instance):
    expected = len(template.fields)          # what the sensor will read
    supplied = len(instance.values)          # what the content provides
    if supplied != expected:
        raise ValueError(f"{supplied} inputs supplied, template defines {expected}")

def read_fields(buf, count):
    if count > len(buf):
        return None          # reject the file, keep running with the last good content
    return buf[:count]
